                    frameUrl: referrerUrl,
                    frameDomain: (0,background_es6/* getDomain */.FB)(referrerUrl),
                    requestType: background_ContentType.Csp,
                    filterId: rule.getFilterListId(),
                    ruleIndex: rule.getIndex(),
                    appliedRuleText,
                    originalRuleText,
                    timestamp: Date.now(),
                    isAllowlist: rule.isAllowlist(),
                    isImportant: rule.isOptionEnabled(background_es/* NetworkRuleOption */.iR.Important),
