                isImportant: appliedRule?.isOptionEnabled(background_es/* NetworkRuleOption */.iR.Important) ?? false,
                isDocumentLevel: appliedRule?.isDocumentLevelAllowlistRule() ?? false,
                isCsp: appliedRule?.isOptionEnabled(background_es/* NetworkRuleOption */.iR.Csp) ?? false,
                isCookie: appliedRule?.isOptionEnabled(background_es/* NetworkRuleOption */.iR.Cookie) ?? false,
                advancedModifier: appliedRule?.getAdvancedModifierValue() ?? null,
                companyCategoryName,
