const background_NINETY_DAYS_MS = 90 * 24 * 60 * 60 * 1000;
class background_UpdateService {
    static async update({ currentAppVersion }) {
        await background_browserModel.set(background_APP_VERSION_KEY, currentAppVersion);
        const lastUpdate = await background_browserModel.get(background_LAST_UPDATE_KEY) || 0;
        const now = Date.now();
        if (now - lastUpdate > background_NINETY_DAYS_MS) {
            // FIREFOX_CONSENT: MV2 sends no params until data_collection_permissions is set up
            let params = {};
            if (true) {
                const isPinned = await background_InstallService.isPinnedToToolbar();
                params = {
                    version: currentAppVersion,
                    browser: background_user_agent_UserAgent.browserName,
                    p: isPinned ? '1' : '0'
                };
            }
            await background_browser_polyfill.tabs.create({
                url: background_buildUrl(background_Endpoint.Updated, params)
            });
        }
        await background_browserModel.set(background_LAST_UPDATE_KEY, now);
    }
}

