function background_document_block_define_property(obj, key, value) {
    if (key in obj) {
        Object.defineProperty(obj, key, {
            value: value,
            enumerable: true,
            configurable: true,
            writable: true
        });
    } else obj[key] = value;
    return obj;
}





class background_DocumentBlockService {
    static async init() {
        try {
            const storageData = await background_trustedDomainsModel.read();
            if (typeof storageData === 'string') {
                background_trustedDomainsModel.setCache(JSON.parse(storageData));
            } else {
                await background_trustedDomainsModel.setData([]);
            }
        } catch (e) {
            await background_trustedDomainsModel.setData([]);
        }
    }
    static async getTrustedDomains() {
        const now = Date.now();
        // remove expired
        const data = background_trustedDomainsModel.getData().filter(({ expires })=>now < expires);
        await background_trustedDomainsModel.setData(data);
        return data.map(({ domain })=>domain);
    }
    static async storeTrustedDomain(input) {
        const now = Date.now();
        // remove expired and duplicates
        const data = background_trustedDomainsModel.getData().filter(({ expires, domain })=>now < expires && domain !== input);
        data.push({
            domain: input,
            expires: background_DocumentBlockService.TRUSTED_TTL_MS + now
        });
        await background_trustedDomainsModel.setData(data);
    }
    static async setTrustedDomain(url) {
        const { hostname } = new URL(url);
        background_DocumentBlockService.storeTrustedDomain(hostname);
    }
}
background_document_block_define_property(background_DocumentBlockService, "TRUSTED_TTL_MS", 10 * 1000); // 10 seconds

