class background_MigrationService {
    static async migrateIfNeeded() {
        const { format, storage } = await background_detectStorageFormat();
        if (format === background_StorageFormat.NONE) {
            return {
                migrated: false,
                source: null
            };
        }
        let formatSource = null;
        try {
            // Phase 1: Legacy format migration (if needed)
            if (format === background_StorageFormat.MV2_LEGACY) {
                await background_MV2LegacyMigrator.migrate(storage);
                formatSource = 'mv2-legacy';
            } else if (format === background_StorageFormat.MV3_LEGACY) {
                await background_MV3LegacyMigrator.migrate(storage);
                formatSource = 'mv3-legacy';
            }
            // Phase 2: Version migration chain
            // Runs for all users (legacy just migrated, or existing CURRENT format).
            // app-version is read here, before InstallService/UpdateService overwrites it.
            // For CURRENT format (no Phase 1 ran), pass the already-read storage to avoid re-reads.
            const effectiveStorage = formatSource ? null : storage;
            const storedVersion = background_getStoredAppVersion(effectiveStorage);
            const settings = effectiveStorage?.[background_SETTINGS_KEY] ?? null;
            const versionMigrated = await background_runVersionMigrations(storedVersion, settings);
            if (formatSource) {
                return {
                    migrated: true,
                    source: formatSource
                };
            }
            if (versionMigrated) {
                return {
                    migrated: true,
                    source: 'version-chain'
                };
            }
            if (format === background_StorageFormat.CURRENT) {
                background_logger_logger.debug('[ext.MigrationService]: Current format, no migrations needed');
            }
        } catch (error) {
            background_logger_logger.error('[ext.MigrationService]: Migration failed:', error);
            return {
                migrated: false,
                source: formatSource,
                error
            };
        }
        return {
            migrated: false,
            source: null
        };
    }
}

